/**
 * Product Finder Routes — Per-supplier search, combined search, and import endpoints.
 *
 * GET  /search?ean=XXX&supplier=dst          — EAN search for specific supplier
 * GET  /search?q=keyword&supplier=kruitbosch — Keyword search for specific supplier
 * GET  /search/all?ean=XXX                   — Search all suppliers (combined)
 * POST /sync/kruitbosch                      — Sync Kruitbosch catalog
 * POST /import                               — Import product into local catalog
 * GET  /suppliers                            — List available suppliers
 */

import { Hono } from 'hono'
import {
  searchSupplierByEan,
  searchSupplierByKeyword,
  searchAllByEan,
  searchAllByKeyword,
  syncSupplier,
  getAuthStatus
} from '../services/search-service.js'
import { importProduct } from '../services/import-service.js'
import { getSupplierList } from '../services/suppliers/index.js'
import { getDstDetail } from '../services/suppliers/dst/detail-service.js'
import { getKruitboschDetail } from '../services/suppliers/kruitbosch/detail-service.js'
import { getGransierDetail } from '../services/suppliers/gransier/detail-service.js'

// ============================================================================
// GET /suppliers — List available suppliers (async, includes sync status)
// ============================================================================

const productFinderRoutes = new Hono()

// ============================================================================
// GET /search — Per-supplier search (EAN or keyword)
// ============================================================================

productFinderRoutes.get('/search', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const supplier = c.req.query('supplier') || 'dst' // default to dst for backward compat
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchSupplierByEan(supplier, ean)
    } else {
      result = await searchSupplierByKeyword(supplier, q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search] Error:', err instanceof Error ? err.message : String(err))
    const status = getAuthStatus()
    if (!status.authenticated) {
      return c.json({ error: 'Not authenticated. Please log in to DST first.', offers: [] }, 401)
    }
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// GET /search/all — Combined search across all suppliers
// ============================================================================

productFinderRoutes.get('/search/all', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchAllByEan(ean)
    } else {
      result = await searchAllByKeyword(q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search/all] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// POST /sync/:supplier — Sync catalog from a supplier (e.g. Kruitbosch)
// ============================================================================

productFinderRoutes.post('/sync/:supplier', async (c) => {
  const supplierId = c.req.param('supplier')

  try {
    const result = await syncSupplier(supplierId)
    return c.json(result)
  } catch (err) {
    console.error(`[POST /product-finder/sync/${supplierId}] Error:`, err instanceof Error ? err.message : String(err))
    return c.json({ success: false, importedCount: 0, error: err instanceof Error ? err.message : 'Unknown error' }, 500)
  }
})

// ============================================================================
// GET /suppliers — List available suppliers (async, includes sync status)
// ============================================================================

productFinderRoutes.get('/suppliers', async (c) => {
  const list = await getSupplierList()
  return c.json({ suppliers: list })
})

// ============================================================================
// POST /import — Import product into local catalog
// ============================================================================

interface ImportRequest {
  eanUpc: string
  name: string
  sellPrice: number
  costPrice: number
  supplierName: string
}

productFinderRoutes.post('/import', async (c) => {
  try {
    const body = await c.req.json() as ImportRequest

    if (!body.eanUpc || !body.name || body.sellPrice == null || body.costPrice == null || !body.supplierName) {
      return c.json({ success: false, action: 'updated', message: 'Missing required fields: eanUpc, name, sellPrice, costPrice, supplierName' }, 400)
    }

    const result = await importProduct(body)

    if (!result.success) {
      return c.json(result, 422)
    }

    return c.json(result, 200)
  } catch (err) {
    console.error('[POST /product-finder/import] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ success: false, action: 'updated', message: `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}` }, 500)
  }
})

// ============================================================================
// GET /auth/status — Authentication status (legacy endpoint)
// ============================================================================

productFinderRoutes.get('/auth/status', (c) => {
  const status = getAuthStatus()
  return c.json(status)
})

// ============================================================================
// GET /kruitbosch/detail?ean=XXX — Kruitbosch product detail endpoint
// ===========================================================================

productFinderRoutes.get('/kruitbosch/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getKruitboschDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in Kruitbosch catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/kruitbosch/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

