export const stockMovements = sqliteTable('stock_movements', {
  id: text('id').primaryKey(),
  partId: text('part_id').notNull().references(() => parts.id),
  quantityDelta: integer('quantity_delta', { mode: 'number' }).notNull(), // positive or negative
  reason: text('reason', { enum: ['sale', 'void', 'order_receive', 'manual_correction', 'backorder_receive', 'repair_use', 'return', 'waste', 'initial_stock', 'adjustment'] }).notNull(),
  referenceType: text('reference_type'), // e.g. 'sale', 'supplier_order_line'
  referenceId: text('reference_id'), // ID of source operation
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  partIdIdx: index('stock_movements_part_id_idx').on(table.partId),
  reasonIdx: index('stock_movements_reason_idx').on(table.reason),
}))

