import { describe, it, expect, beforeEach } from 'vitest'
import { db } from '@/db/index.js'
import { parts, stockMovements, supplierProducts, vatRates } from '@/db/schema.js'
import { eq, and, sql } from 'drizzle-orm'
import { importProduct } from '../import-service.js'

describe('Import Service', () => {
  async function resetData() {
    await db.delete(parts)
    await db.delete(supplierProducts)
    // Ensure at least one VAT rate exists for price calculation
    const existingRates = await db.select({ id: vatRates.id }).from(vatRates)
    if (existingRates.length === 0) {
      await db.insert(vatRates).values({ id: 'standard', rate: 2100, description: 'Standard VAT' })
    }
  }

  beforeEach(async () => {
    await resetData()
  })

  // ── Create Path (New Part) ────────────────────────────────────────────

  describe('create path — new part', () => {
    it('should create a new part with correct fields', async () => {
      const result = await importProduct({
        eanUpc: '8712345678901',
        name: 'Schijfrem MT200',
        sellPrice: 2479, // net cents
        costPrice: 1488, // net cents
        supplierName: 'DST Suppliers'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('created')
      expect(result.partId).toBeDefined()
      expect(result.message).toContain('New part created')

      // Verify the part was created in the database
      const partByBarcode = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678901')
      ).limit(1)

      expect(partByBarcode.length).toBe(1)
      expect(partByBarcode[0].barcode).toBe('8712345678901')
      expect(partByBarcode[0].name).toBe('Schijfrem MT200')
      expect(partByBarcode[0].priceNet).toBe(2479)
      expect(partByBarcode[0].costPrice).toBe(1488)
      expect(partByBarcode[0].quantityOnHand).toBe(0)
    })

    it('should set isActive to true for new parts', async () => {
      await importProduct({
        eanUpc: '8712345678902',
        name: 'Ketting 12-speed',
        sellPrice: 4132,
        costPrice: 2479,
        supplierName: 'DST Suppliers'
      })

      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678902')
      ).limit(1)

      expect(part[0].isActive).toBe(true)
    })

    it('should use provided quantityOnHand when importing with stock', async () => {
      const result = await importProduct({
        eanUpc: '8712345678906',
        name: 'Chainring 50T',
        sellPrice: 3200,
        costPrice: 1900,
        supplierName: 'DST Suppliers',
        quantityOnHand: 12
      })

      expect(result.success).toBe(true)
      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678906')
      ).limit(1)

      expect(part[0].quantityOnHand).toBe(12)
    })

    it('should create an order_receive stock movement when importing with quantity > 0', async () => {
      await importProduct({
        eanUpc: '8712345678907',
        name: 'Bearing 6205',
        sellPrice: 500,
        costPrice: 300,
        supplierName: 'DST Suppliers',
        quantityOnHand: 20
      })

      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678907')
      ).limit(1)

      const movements = await db.select()
        .from(stockMovements)
        .where(and(
          eq(stockMovements.partId, part[0].id),
          eq(stockMovements.reason, 'order_receive')
        ))

      expect(movements.length).toBe(1)
      expect(movements[0].quantityDelta).toBe(20)
    })

    it('should not create a stock movement when importing with quantity = 0', async () => {
      await importProduct({
        eanUpc: '8712345678908',
        name: 'Bolt M6x20',
        sellPrice: 5,
        costPrice: 2,
        supplierName: 'DST Suppliers'
      })

      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678908')
      ).limit(1)

      const movementCount = await db.select({ count: sql<number>`count(*)` })
        .from(stockMovements)
        .where(eq(stockMovements.partId, part[0].id))

      expect(movementCount[0].count).toBe(0)
    })

    it('should trim whitespace from product name', async () => {
      await importProduct({
        eanUpc: '8712345678903',
        name: '  Shimano Brake Pad  ',
        sellPrice: 1500,
        costPrice: 800,
        supplierName: 'DST Suppliers'
      })

      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678903')
      ).limit(1)

      expect(part[0].name).toBe('Shimano Brake Pad')
    })

    it('should return 422 when required fields are missing', async () => {
      const result = await importProduct({
        eanUpc: '',
        name: 'Test',
        sellPrice: 100,
        costPrice: 50,
        supplierName: 'DST Suppliers'
      })

      expect(result.success).toBe(false)
      expect(result.message).toContain('required')
    })
  })

  // ── Update Path (Existing Part) ───────────────────────────────────────

  describe('update path — existing part', () => {
    beforeEach(async () => {
      // Pre-create a part with stock to test preservation
      await db.insert(parts).values({
        id: 'part-8712345678901',
        barcode: '8712345678901',
        name: 'Old Name',
        priceNet: 1000,
        costPrice: 500,
        quantityOnHand: 15, // Non-zero stock to verify preservation
        isActive: true
      })

      // Also cache the supplier product
      await db.insert(supplierProducts).values({
        id: 'sp-test',
        eanUpc: '8712345678901',
        rawJson: JSON.stringify({ old: 'data' }),
        supplierName: 'DST Suppliers',
        searchedAt: new Date()
      })
    })

    it('should update name and pricing without touching stock levels', async () => {
      const result = await importProduct({
        eanUpc: '8712345678901',
        name: 'New Schijfrem MT200',
        sellPrice: 2479,
        costPrice: 1488,
        supplierName: 'DST Suppliers'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('updated')
      expect(result.message).toContain('stock levels preserved')

      // Verify the part was updated
      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678901')
      ).limit(1)

      expect(part[0].name).toBe('New Schijfrem MT200')
      expect(part[0].priceNet).toBe(2479)
      expect(part[0].costPrice).toBe(1488)
      // Stock level must be preserved!
      expect(part[0].quantityOnHand).toBe(15)
    })

    it('should refresh the supplier product cache on import', async () => {
      await importProduct({
        eanUpc: '8712345678901',
        name: 'New Schijfrem MT200',
        sellPrice: 2479,
        costPrice: 1488,
        supplierName: 'DST Suppliers'
      })

      // Verify the cache was updated
      const cached = await db.select().from(supplierProducts).where(
        eq(supplierProducts.eanUpc, '8712345678901') && eq(supplierProducts.supplierName, 'DST Suppliers')
      ).limit(1)

      expect(cached.length).toBe(1)
      const parsedRaw = JSON.parse(cached[0].rawJson)
      expect(parsedRaw.name).toBe('New Schijfrem MT200')
    })

    it('should preserve stock when updating with different prices', async () => {
      // First import to set initial state
      await db.update(parts).set({ priceNet: 1500, costPrice: 750 }).where(
        eq(parts.barcode, '8712345678901')
      )

      const result = await importProduct({
        eanUpc: '8712345678901',
        name: 'Updated Name',
        sellPrice: 3000,
        costPrice: 1800,
        supplierName: 'DST Suppliers'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('updated')

      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678901')
      ).limit(1)

      expect(part[0].priceNet).toBe(3000)
      expect(part[0].costPrice).toBe(1800)
      expect(part[0].quantityOnHand).toBe(15) // Still preserved!
    })
  })

  // ── Kruitbosch Import (Local Catalog Suppliers) ───────────────────────

  describe('kruitbosch import — local catalog supplier', () => {
    it('should create part and refresh cache when supplier_products entry exists', async () => {
      // Pre-create the supplier product cache entry (as would happen during sync)
      await db.insert(supplierProducts).values({
        id: 'sp-kruitbosch-test',
        eanUpc: '8712345678901',
        rawJson: JSON.stringify({
          ean_upc: '8712345678901',
          name: 'Original Kruitbosch Product',
          brand: 'Kruitbosch Brand',
          recommended_retailprice: 50,
          gross_purchase_price: 30
        }),
        supplierName: 'Kruitbosch',
        searchedAt: new Date()
      })

      const result = await importProduct({
        eanUpc: '8712345678901',
        name: 'Updated Kruitbosch Product',
        sellPrice: 4500, // net cents
        costPrice: 2800, // net cents
        supplierName: 'Kruitbosch'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('created')
      expect(result.partId).toBeDefined()

      // Verify the cache was refreshed with import data
      const cached = await db.select().from(supplierProducts).where(
        eq(supplierProducts.eanUpc, '8712345678901') && eq(supplierProducts.supplierName, 'Kruitbosch')
      ).limit(1)

      expect(cached.length).toBe(1)
      const parsedRaw = JSON.parse(cached[0].rawJson)
      expect(parsedRaw.name).toBe('Updated Kruitbosch Product')
      expect(parsedRaw.supplierName).toBe('Kruitbosch')
    })

    it('should create supplier_products entry when importing without prior sync', async () => {
      // No pre-existing supplier_products entry — simulates import before sync
      const result = await importProduct({
        eanUpc: '8712345678910',
        name: 'Kruitbosch Product Without Sync',
        sellPrice: 3000,
        costPrice: 1500,
        supplierName: 'Kruitbosch'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('created')

      // Verify the cache entry was created
      const cached = await db.select().from(supplierProducts).where(
        eq(supplierProducts.eanUpc, '8712345678910') && eq(supplierProducts.supplierName, 'Kruitbosch')
      ).limit(1)

      expect(cached.length).toBe(1)
      const parsedRaw = JSON.parse(cached[0].rawJson)
      expect(parsedRaw.name).toBe('Kruitbosch Product Without Sync')
      expect(parsedRaw.supplierName).toBe('Kruitbosch')
    })

    it('should update existing part and create cache entry for kruitbosch', async () => {
      // Pre-create a part but NO supplier_products entry
      await db.insert(parts).values({
        id: 'part-8712345678920',
        barcode: '8712345678920',
        name: 'Old Kruitbosch Part',
        priceNet: 2000,
        costPrice: 1000,
        quantityOnHand: 5,
        isActive: true
      })

      const result = await importProduct({
        eanUpc: '8712345678920',
        name: 'New Kruitbosch Part Name',
        sellPrice: 3500,
        costPrice: 1800,
        supplierName: 'Kruitbosch'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('updated')

      // Verify part was updated
      const part = await db.select().from(parts).where(
        eq(parts.barcode, '8712345678920')
      ).limit(1)

      expect(part[0].name).toBe('New Kruitbosch Part Name')
      expect(part[0].priceNet).toBe(3500)
      expect(part[0].costPrice).toBe(1800)
      expect(part[0].quantityOnHand).toBe(5) // Stock preserved

      // Verify cache entry was created (not just updated)
      const cached = await db.select().from(supplierProducts).where(
        eq(supplierProducts.eanUpc, '8712345678920') && eq(supplierProducts.supplierName, 'Kruitbosch')
      ).limit(1)

      expect(cached.length).toBe(1)
    })
  })

  // ── Gransier Import (Local Catalog Suppliers) ─────────────────────────

  describe('gransier import — local catalog supplier', () => {
    it('should create part and cache entry for gransier without prior sync', async () => {
      const result = await importProduct({
        eanUpc: '8712345678930',
        name: 'Gransier Product Without Sync',
        sellPrice: 2500,
        costPrice: 1200,
        supplierName: 'Gransier'
      })

      expect(result.success).toBe(true)
      expect(result.action).toBe('created')

      // Verify the cache entry was created
      const cached = await db.select().from(supplierProducts).where(
        eq(supplierProducts.eanUpc, '8712345678930') && eq(supplierProducts.supplierName, 'Gransier')
      ).limit(1)

      expect(cached.length).toBe(1)
    })
  })

  // ── Edge Cases ────────────────────────────────────────────────────────

  describe('edge cases', () => {
    it('should handle duplicate EAN with different supplier names as separate parts', async () => {
      const result1 = await importProduct({
        eanUpc: '8712345678901',
        name: 'Part from Supplier A',
        sellPrice: 1000,
        costPrice: 500,
        supplierName: 'Supplier A'
      })

      expect(result1.success).toBe(true)
      expect(result1.action).toBe('created')

      const result2 = await importProduct({
        eanUpc: '8712345678901',
        name: 'Part from Supplier B',
        sellPrice: 1200,
        costPrice: 600,
        supplierName: 'Supplier B'
      })

      // Same EAN but different supplier — should update the existing part (by barcode)
      expect(result2.success).toBe(true)
      expect(result2.action).toBe('updated')
    })

    it('should return created action for first import of a unique EAN', async () => {
      const result = await importProduct({
        eanUpc: '8712345678904',
        name: 'Unique Part',
        sellPrice: 500,
        costPrice: 250,
        supplierName: 'DST Suppliers'
      })

      expect(result.action).toBe('created')
    })

    it('should handle empty name validation', async () => {
      const result = await importProduct({
        eanUpc: '8712345678905',
        name: '',
        sellPrice: 100,
        costPrice: 50,
        supplierName: 'DST Suppliers'
      })

      expect(result.success).toBe(false)
    })
  })
})
